const body = $input.first().json.body || $input.first().json;
return [{ json: {
  question:    body.question || body.query || body.message || '',
  utilisateur: body.utilisateur || body.user || 'Participant',
  session_id:  body.session_id || 'sess-' + Date.now(),
  timestamp:   new Date().toISOString()
}}];

const payload = $input.first().json;
const rawDocs = Array.isArray(payload)
  ? payload
  : Array.isArray(payload?.body)
    ? payload.body
    : Array.isArray(payload?.data)
      ? payload.data
      : payload?.titre || payload?.contenu || payload?.content
        ? [payload]
        : [];
const question = $('Extraire question').first().json.question;
const seen = new Set();
const docs = rawDocs
  .filter((doc) => doc && (doc.contenu || doc.content))
  .map((doc) => ({
    titre: doc.titre || doc.title || 'Sans titre',
    contenu: String(doc.contenu || doc.content || '').trim(),
    url: doc.url || doc.source_url || null,
    similarite: Math.round(Math.max(0, Math.min(1, Number(doc.similarity || doc.score || 0))) * 100),
    source_id: doc.source_id || null,
    chunk_index: doc.chunk_index ?? null,
  }))
  .filter((doc) => {
    const key = `${doc.source_id || doc.titre}::${doc.chunk_index ?? 'na'}::${doc.url || 'no-url'}`;
    if (seen.has(key)) return false;
    seen.add(key);
    return true;
  })
  .slice(0, 6);

const contexte = docs.map((doc, index) => {
  const extrait = doc.contenu.length > 900 ? `${doc.contenu.slice(0, 899).trimEnd()}…` : doc.contenu;
  return `[Document ${index + 1}] ${doc.titre} (similarite: ${doc.similarite}%)\n${extrait}`;
}).join('\n\n---\n\n');

const sources = docs.map((doc) => ({
  titre: doc.titre,
  url: doc.url,
  similarite: doc.similarite,
}));

return [{ json: {
  question,
  contexte_rag: contexte || 'Aucun document pertinent n\'a ete trouve dans la base documentaire.',
  sources,
  nb_sources: docs.length,
}}];

