const gpt = $input.first().json;
const reponse = gpt?.choices?.[0]?.message?.content || 'Je n\'ai pas pu formuler une reponse exploitable a partir des documents indexes.';
const meta = $('Construire contexte RAG').first().json;

return [{ json: {
  reponse,
  question: meta.question,
  sources: meta.sources,
  nb_sources: meta.nb_sources,
  timestamp: new Date().toISOString()
}}];
